let fractalType;

let xOffset, yOffset;
let xScale, yScale;

let heightmap;
var unicoord = [];
let colorray = new Array(5048);

//__________________________________________________________________________________________________

function setup() {
  createCanvas(windowWidth, windowHeight);

  let xSize = 7;
  let ySize = xSize * height / width;
  xOffset = -xSize/2;
  yOffset = -ySize/2;
  xScale = width/xSize;
	yScale = height/ySize;

  heightmap = new Array(width*height);
  clearHeightmap();

  unicoord = new Array(width)[height];
  let pixel = 0;
  for (let y = 0; y < height; y++) {
    for (let x = 0; x < width; x++) {
      unicoord[x][y] = pixel++;
    }
  }

  changeColors();
  loadPixels();
}

