  for (let i = 0; i < pixels.length; i++) {
    pixels[i] = colorray[int(log(heightmap[i]) * 64)];
  }

  updatePixels();
}

//__________________________________________________________________________________________________

function changeColors() {
  let r = random(256);
  let g = random(256);
  let b = random(256);

  let vr = 0;
  let vg = 0;
  let vb = 0;

  for (let i = colorray.length - 1; i > -1; i--) {
    colorray[i] = color(r, g, b);

    vr += randomGaussian() * 0.04;
    vg += randomGaussian() * 0.04;
    vb += randomGaussian() * 0.04;

    r += vr;
    g += vg;
    b += vb;

    if ((r < 0 && vr < 0) || (r > 255 && vr > 0))    vr = -vr;
    if ((g < 0 && vg < 0) || (g > 255 && vg > 0))    vg = -vg;
    if ((b < 0 && vb < 0) || (b > 255 && vb > 0))    vb = -vb;
  }
}

//__________________________________________________________________________________________________

function clearHeightmap() {
  for (let i = 0; i < heightmap.length; i++) {
    heightmap[i] = 1;
  }
}

//__________________________________________________________________________________________________

function mousePressed() {
  if (mouseButton == LEFT) {
    fractalType = (fractalType + 1) % 21;
    changeColors();
    clearHeightmap();
  }
  else if (mouseButton == RIGHT) {
    changeColors();
  }
}
















function fractal0() {
  for (let n = 0; n < 1024; n++) {
    let ia = randomGaussian();
    let ib = randomGaussian();
    let a = ia;
    let b = ib;

    for (let i = 0; i < 1024; i++) {
			let ta = sin(a*a+b*b)+ia;
      b = sin(a)+sin(b);
      a = ta;

      let x = int((b-xOffset)*xScale);
      let y = int((a-yOffset)*yScale);

      if (x > -1 && x < width && y > -1 && y < height) {
        heightmap[unicoord[x][y]]++;
      }
      else {
        break;
      }
    }
  }
}

